import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Lq8Lraw_.js";const u=JSON.parse('{"title":"命令速查表","description":"","frontmatter":{},"headers":[],"relativePath":"guide/appendix/01-cheatsheet.md","filePath":"guide/appendix/01-cheatsheet.md","lastUpdated":1792671989000}'),r={name:"guide/appendix/01-cheatsheet.md"};function a(i,t,l,g,s,h){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="命令速查表" tabindex="-1">命令速查表 <a class="header-anchor" href="#命令速查表" aria-label="Permalink to &quot;命令速查表&quot;">​</a></h1><p>按使用场景分类，覆盖全站出现的命令。表格中「常用参数」列只列真正会改变行为的那几个，完整参数用 <code>git help &lt;command&gt;</code> 查看。</p><div class="tip custom-block"><p class="custom-block-title">阅读方式</p><p>命令中的 <code>&lt;...&gt;</code> 需要替换，方括号 <code>[...]</code> 表示可选。所有示例在 Git 2.40+ 可用。涉及改写历史或删除数据的命令，统一列在文末「危险命令清单」。</p></div><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git config --global user.name &quot;&lt;名字&gt;&quot;</code></td><td>设置提交作者名</td><td><code>--global</code> / <code>--local</code> / <code>--system</code></td></tr><tr><td><code>git config --global user.email &quot;&lt;邮箱&gt;&quot;</code></td><td>设置提交邮箱</td><td>同上</td></tr><tr><td><code>git config --global core.editor &quot;code --wait&quot;</code></td><td>设置提交信息编辑器</td><td>支持任意编辑器命令</td></tr><tr><td><code>git config --global init.defaultBranch main</code></td><td>新仓库默认分支名</td><td>替代 <code>master</code></td></tr><tr><td><code>git config --global pull.ff only</code></td><td>禁止 <code>pull</code> 产生意外合并</td><td><code>only</code> / <code>true</code> / <code>false</code></td></tr><tr><td><code>git config --global rerere.enabled true</code></td><td>记住并复用冲突解法</td><td>详见协作篇 rerere</td></tr><tr><td><code>git config --global core.autocrlf false</code></td><td>关闭个人换行转换，交给 <code>.gitattributes</code></td><td>Windows 常用 <code>input</code></td></tr><tr><td><code>git config --list --show-origin</code></td><td>查看全部配置及来源文件</td><td><code>--show-scope</code></td></tr><tr><td><code>git config --get &lt;key&gt;</code></td><td>读取单项配置</td><td><code>--default</code></td></tr><tr><td><code>git config --unset &lt;key&gt;</code></td><td>删除单项配置</td><td><code>--global</code></td></tr><tr><td><code>git config core.hooksPath .githooks</code></td><td>指定钩子目录</td><td>让钩子脚本随仓库分发</td></tr><tr><td><code>git config alias.&lt;别名&gt; &quot;&lt;命令&gt;&quot;</code></td><td>定义命令别名</td><td>不能覆盖内置命令</td></tr><tr><td><code>git help &lt;command&gt;</code> / <code>git &lt;command&gt; -h</code></td><td>查手册 / 快速帮助</td><td><code>-w</code> 打开网页版</td></tr></tbody></table><h2 id="仓库初始化" tabindex="-1">仓库初始化 <a class="header-anchor" href="#仓库初始化" aria-label="Permalink to &quot;仓库初始化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git init</code></td><td>初始化仓库</td><td><code>-b main</code> 指定初始分支</td></tr><tr><td><code>git clone &lt;url&gt;</code></td><td>克隆远程仓库</td><td><code>--depth 1</code> 浅克隆；<code>--branch &lt;b&gt;</code></td></tr><tr><td><code>git clone --recurse-submodules &lt;url&gt;</code></td><td>克隆并初始化子模块</td><td><code>--shallow-submodules</code></td></tr><tr><td><code>git remote add origin &lt;url&gt;</code></td><td>添加远程</td><td><code>git remote set-url</code> 改地址</td></tr><tr><td><code>git remote -v</code></td><td>列出远程及 URL</td><td><code>-v</code> 显示 fetch/push 地址</td></tr><tr><td><code>git status</code></td><td>查看工作区与暂存区状态</td><td><code>-s</code> 短格式；<code>-b</code> 显示分支</td></tr><tr><td><code>git add &lt;file&gt;</code></td><td>加入暂存区</td><td><code>-A</code> 全部；<code>.</code> 当前目录</td></tr><tr><td><code>git add -p</code></td><td>交互式按块暂存</td><td><code>-i</code> 进入交互模式</td></tr><tr><td><code>git rm --cached &lt;file&gt;</code></td><td>停止跟踪但保留本地文件</td><td><code>-r</code> 递归</td></tr><tr><td><code>git mv &lt;old&gt; &lt;new&gt;</code></td><td>移动/重命名并暂存</td><td>等价于 <code>mv</code> + <code>add</code></td></tr></tbody></table><h2 id="提交" tabindex="-1">提交 <a class="header-anchor" href="#提交" aria-label="Permalink to &quot;提交&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git commit -m &quot;&lt;msg&gt;&quot;</code></td><td>提交暂存内容</td><td><code>-a</code> 跳过暂存（不含新文件）</td></tr><tr><td><code>git commit --amend</code></td><td>修改最后一次提交</td><td><code>--no-edit</code> 只改内容不改信息</td></tr><tr><td><code>git commit --fixup=&lt;hash&gt;</code></td><td>生成待 autosquash 的修正提交</td><td>配合 <code>rebase -i --autosquash</code></td></tr><tr><td><code>git commit --allow-empty -m &quot;&lt;msg&gt;&quot;</code></td><td>空提交，触发 CI</td><td>谨慎使用</td></tr><tr><td><code>git commit --no-verify</code></td><td>跳过客户端提交钩子</td><td>应急场景，见 hooks 章</td></tr><tr><td><code>git log --oneline</code></td><td>精简提交历史</td><td><code>-n 10</code>；<code>--graph</code>；<code>--all</code></td></tr><tr><td><code>git log --reverse --oneline &lt;a&gt;..&lt;b&gt;</code></td><td>按时间正序看区间提交</td><td><code>--stat</code> 附带文件统计</td></tr><tr><td><code>git show &lt;hash&gt;</code></td><td>查看提交详情与 diff</td><td><code>--stat</code>；<code>&lt;hash&gt;:&lt;path&gt;</code> 看文件</td></tr><tr><td><code>git diff</code></td><td>工作区 vs 暂存区</td><td><code>--stat</code>；<code>--word-diff</code></td></tr><tr><td><code>git diff --cached</code></td><td>暂存区 vs HEAD</td><td><code>--name-only</code>；<code>-U0</code></td></tr><tr><td><code>git diff HEAD~1 HEAD</code></td><td>两个提交之间比较</td><td><code>-- &lt;path&gt;</code> 限定路径</td></tr><tr><td><code>git stash push -m &quot;&lt;说明&gt;&quot;</code></td><td>临时保存工作区</td><td><code>-u</code> 含未跟踪文件</td></tr><tr><td><code>git stash list</code></td><td>查看 stash 列表</td><td><code>-p</code> 显示内容</td></tr><tr><td><code>git stash pop</code></td><td>恢复并删除最新 stash</td><td><code>stash@{n}</code> 指定</td></tr><tr><td><code>git stash apply</code></td><td>恢复但保留 stash</td><td>适合多处复用</td></tr><tr><td><code>git stash drop</code></td><td>删除指定 stash</td><td><code>stash@{n}</code></td></tr><tr><td><code>git shortlog -sn --no-merges</code></td><td>按作者统计提交数</td><td>发布说明常用</td></tr></tbody></table><h2 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to &quot;分支&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git branch</code></td><td>列出本地分支</td><td><code>-a</code> 含远程；<code>-vv</code> 含 upstream</td></tr><tr><td><code>git branch &lt;name&gt;</code></td><td>创建分支，不切换</td><td><code>&lt;name&gt; &lt;start-point&gt;</code> 指定起点</td></tr><tr><td><code>git branch -d &lt;name&gt;</code></td><td>删除已合并分支</td><td><code>-D</code> 强制删除</td></tr><tr><td><code>git branch -m &lt;old&gt; &lt;new&gt;</code></td><td>重命名分支</td><td><code>-M</code> 强制覆盖</td></tr><tr><td><code>git branch -u origin/&lt;name&gt;</code></td><td>设置上游跟踪</td><td><code>--unset-upstream</code> 解除</td></tr><tr><td><code>git switch &lt;branch&gt;</code></td><td>切换分支</td><td><code>-</code> 回到上一个分支</td></tr><tr><td><code>git switch -c &lt;branch&gt;</code></td><td>创建并切换</td><td><code>-c &lt;b&gt; &lt;start-point&gt;</code></td></tr><tr><td><code>git switch --detach &lt;hash&gt;</code></td><td>分离头指针检出</td><td>临时查看历史</td></tr><tr><td><code>git checkout &lt;hash&gt;</code></td><td>旧式检出（含文件）</td><td><code>-- &lt;file&gt;</code> 还原文件</td></tr><tr><td><code>git merge-base &lt;a&gt; &lt;b&gt;</code></td><td>找共同祖先</td><td><code>--all</code></td></tr><tr><td><code>git show-branch</code></td><td>分支分叉关系</td><td><code>--all</code></td></tr></tbody></table><h2 id="合并与变基" tabindex="-1">合并与变基 <a class="header-anchor" href="#合并与变基" aria-label="Permalink to &quot;合并与变基&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git merge &lt;branch&gt;</code></td><td>合并分支</td><td><code>--no-ff</code> 保留合并提交</td></tr><tr><td><code>git merge --squash &lt;branch&gt;</code></td><td>压缩为一个待提交变更</td><td>需手动 <code>commit</code></td></tr><tr><td><code>git merge --abort</code></td><td>放弃本次合并</td><td>恢复到合并前</td></tr><tr><td><code>git merge --continue</code></td><td>解决冲突后继续</td><td>需先 <code>git add</code></td></tr><tr><td><code>git rebase &lt;base&gt;</code></td><td>把当前分支变基到 base</td><td><code>--rebase-merges</code> 保留合并结构</td></tr><tr><td><code>git rebase -i HEAD~&lt;n&gt;</code></td><td>交互式整理最近 n 个提交</td><td><code>pick</code>/<code>reword</code>/<code>squash</code>/<code>drop</code></td></tr><tr><td><code>git rebase -i --autosquash &lt;base&gt;</code></td><td>自动合并 fixup 提交</td><td>配合 <code>commit --fixup</code></td></tr><tr><td><code>git rebase --onto &lt;new&gt; &lt;old&gt; &lt;branch&gt;</code></td><td>把区间搬到新基底</td><td>精确搬迁</td></tr><tr><td><code>git rebase --continue</code></td><td>冲突解决后继续</td><td>先 <code>git add</code></td></tr><tr><td><code>git rebase --skip</code></td><td>跳过当前提交</td><td>该提交内容会丢失</td></tr><tr><td><code>git rebase --abort</code></td><td>放弃变基</td><td>回到 <code>ORIG_HEAD</code></td></tr><tr><td><code>git cherry-pick &lt;hash&gt;</code></td><td>搬运单个提交</td><td><code>-x</code> 记录来源；<code>-n</code> 不提交</td></tr><tr><td><code>git cherry-pick &lt;a&gt;^..&lt;b&gt;</code></td><td>搬运区间</td><td>左开右闭需注意 <code>^</code></td></tr><tr><td><code>git revert &lt;hash&gt;</code></td><td>生成反向提交</td><td><code>-m 1</code> 回滚合并提交</td></tr><tr><td><code>git rerere status</code> / <code>git rerere diff</code></td><td>查看冲突解法记录</td><td>需先启用 <code>rerere.enabled</code></td></tr></tbody></table><h2 id="远程" tabindex="-1">远程 <a class="header-anchor" href="#远程" aria-label="Permalink to &quot;远程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git fetch origin</code></td><td>拉取远端更新，不改工作区</td><td><code>--prune</code> 清理失效远程分支</td></tr><tr><td><code>git fetch --all --prune</code></td><td>拉取所有远程并清理</td><td>定期执行</td></tr><tr><td><code>git pull --ff-only</code></td><td>仅快进拉取</td><td>避免隐式合并</td></tr><tr><td><code>git pull --rebase</code></td><td>拉取后变基本地提交</td><td><code>--autostash</code></td></tr><tr><td><code>git push -u origin &lt;branch&gt;</code></td><td>首次推送并设置 upstream</td><td><code>-u</code> 只需一次</td></tr><tr><td><code>git push</code></td><td>推送当前分支</td><td><code>--tags</code>；<code>--follow-tags</code></td></tr><tr><td><code>git push --force-with-lease</code></td><td>安全强推，远端被他人更新则失败</td><td>改写历史后唯一推荐方式</td></tr><tr><td><code>git push origin --delete &lt;branch&gt;</code></td><td>删除远端分支</td><td>确认无 PR 依赖</td></tr><tr><td><code>git push origin --delete tag &lt;tag&gt;</code></td><td>删除远端标签</td><td>本地 <code>git tag -d</code> 另行删除</td></tr><tr><td><code>git branch -vv</code></td><td>查看本地分支与 upstream 差距</td><td><code>-vvv</code> 更详细</td></tr><tr><td><code>git remote prune origin</code></td><td>清理本地残留的远程分支引用</td><td>等价于 <code>fetch --prune</code></td></tr></tbody></table><h2 id="撤销与恢复" tabindex="-1">撤销与恢复 <a class="header-anchor" href="#撤销与恢复" aria-label="Permalink to &quot;撤销与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git restore &lt;file&gt;</code></td><td>用暂存区内容覆盖工作区</td><td><code>--source=&lt;hash&gt;</code> 指定来源</td></tr><tr><td><code>git restore --staged &lt;file&gt;</code></td><td>取消暂存，工作区不变</td><td><code>--source=HEAD</code></td></tr><tr><td><code>git restore -p &lt;file&gt;</code></td><td>交互式丢弃部分改动</td><td>危险，逐块确认</td></tr><tr><td><code>git reset --soft HEAD~1</code></td><td>撤销提交，改动留在暂存区</td><td>保留内容首选</td></tr><tr><td><code>git reset HEAD~1</code></td><td>撤销提交并取消暂存</td><td>默认 <code>--mixed</code></td></tr><tr><td><code>git reset --hard HEAD~1</code></td><td>撤销提交并丢弃改动</td><td>危险，可用 reflog 恢复</td></tr><tr><td><code>git reset --hard &lt;hash&gt;</code></td><td>回到指定提交</td><td>先建备份分支</td></tr><tr><td><code>git revert &lt;hash&gt;</code></td><td>反向提交，不改历史</td><td>已推送场景首选</td></tr><tr><td><code>git clean -n</code></td><td>预览将被删除的未跟踪文件</td><td>先预览再执行</td></tr><tr><td><code>git clean -fd</code></td><td>删除未跟踪文件与目录</td><td><code>-x</code> 连忽略文件一起删</td></tr><tr><td><code>git reflog</code></td><td>查看 HEAD 移动历史</td><td><code>-n 20</code>；<code>--date=iso</code></td></tr><tr><td><code>git reflog show &lt;branch&gt;</code></td><td>查看分支指针历史</td><td>恢复误删分支用</td></tr><tr><td><code>git branch &lt;name&gt; &lt;hash&gt;</code></td><td>用历史哈希重建分支</td><td>救援第一步</td></tr><tr><td><code>git fsck --lost-found --no-reflogs</code></td><td>找悬空提交</td><td>输出在 <code>.git/lost-found/</code></td></tr><tr><td><code>git cat-file -t &lt;hash&gt;</code></td><td>确认对象类型</td><td><code>commit</code> / <code>tree</code> / <code>blob</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">三区撤销速查</p><table tabindex="0"><thead><tr><th>想撤销什么</th><th>命令</th></tr></thead><tbody><tr><td>工作区改动</td><td><code>git restore &lt;file&gt;</code></td></tr><tr><td>暂存区（unstage）</td><td><code>git restore --staged &lt;file&gt;</code></td></tr><tr><td>最后一次提交但保留改动</td><td><code>git reset --soft HEAD~1</code></td></tr><tr><td>提交并丢弃改动</td><td><code>git reset --hard HEAD~1</code></td></tr><tr><td>已推送的提交</td><td><code>git revert &lt;hash&gt;</code></td></tr></tbody></table></div><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git blame &lt;file&gt;</code></td><td>逐行查看最后修改者</td><td><code>-L 10,20</code> 限定行；<code>-C</code> 追踪移动</td></tr><tr><td><code>git log -S &quot;&lt;文本&gt;&quot;</code></td><td>查找增删该文本的提交（pickaxe）</td><td><code>--oneline</code>；<code>-- &lt;path&gt;</code></td></tr><tr><td><code>git log -G &quot;&lt;正则&gt;&quot;</code></td><td>按 diff 内容正则查找</td><td><code>-p</code> 显示补丁</td></tr><tr><td><code>git log --follow -- &lt;file&gt;</code></td><td>跟踪文件重命名历史</td><td>单文件常用</td></tr><tr><td><code>git log --all --oneline --graph --decorate</code></td><td>全局分支图</td><td>可配合 alias <code>lg</code></td></tr><tr><td><code>git bisect start</code></td><td>开始二分定位</td><td>见 <a href="/git-tutorial-site/guide/mastery/02-bisect">bisect</a></td></tr><tr><td><code>git bisect run &lt;script&gt;</code></td><td>自动二分</td><td>0 好 / 1 坏 / 125 跳过</td></tr><tr><td><code>git bisect reset</code></td><td>结束二分并回到原分支</td><td>必须执行</td></tr><tr><td><code>git diff --check</code></td><td>检查空白错误与冲突标记</td><td>提交前常用</td></tr><tr><td><code>git grep &quot;&lt;pattern&gt;&quot; -- &lt;path&gt;</code></td><td>在仓库中搜索内容</td><td><code>-n</code>；<code>-i</code></td></tr><tr><td><code>git check-attr -a -- &lt;file&gt;</code></td><td>查看文件生效的 Git 属性</td><td>排查 <code>.gitattributes</code></td></tr><tr><td><code>git ls-files --eol -- &lt;path&gt;</code></td><td>查看索引/工作区换行符</td><td>排查 CRLF/LF 问题</td></tr><tr><td><code>git rev-parse HEAD</code></td><td>输出当前提交完整哈希</td><td><code>--short</code>；<code>--abbrev-ref HEAD</code></td></tr><tr><td><code>git show-ref</code></td><td>列出全部引用及哈希</td><td><code>--heads</code>；<code>--tags</code></td></tr><tr><td><code>git count-objects -vH</code></td><td>查看仓库对象占用</td><td>清理前评估</td></tr><tr><td><code>git gc</code></td><td>垃圾回收与压缩</td><td><code>--prune=now</code> 危险</td></tr><tr><td><code>git fsck</code></td><td>校验对象库完整性</td><td><code>--full</code></td></tr></tbody></table><h2 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git tag</code></td><td>列出标签</td><td><code>-l &quot;v1.*&quot;</code> 过滤</td></tr><tr><td><code>git tag &lt;name&gt;</code></td><td>创建轻量标签</td><td>指向当前 HEAD</td></tr><tr><td><code>git tag -a &lt;name&gt; -m &quot;&lt;说明&gt;&quot;</code></td><td>创建附注标签</td><td>发布版本推荐</td></tr><tr><td><code>git tag -s &lt;name&gt; -m &quot;&lt;说明&gt;&quot;</code></td><td>创建 GPG 签名标签</td><td>需配置签名密钥</td></tr><tr><td><code>git tag -d &lt;name&gt;</code></td><td>删除本地标签</td><td>远端需单独删除</td></tr><tr><td><code>git push origin &lt;tag&gt;</code></td><td>推送单个标签</td><td><code>--follow-tags</code> 随提交推附注标签</td></tr><tr><td><code>git push origin --tags</code></td><td>推送全部标签</td><td>会推送轻量标签</td></tr><tr><td><code>git describe --tags --always</code></td><td>生成基于标签的版本描述</td><td><code>--dirty</code> 标记未提交改动</td></tr><tr><td><code>git checkout &lt;tag&gt;</code></td><td>检出标签（分离头指针）</td><td>发版构建常用</td></tr></tbody></table><h2 id="子模块与子树" tabindex="-1">子模块与子树 <a class="header-anchor" href="#子模块与子树" aria-label="Permalink to &quot;子模块与子树&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>常用参数</th></tr></thead><tbody><tr><td><code>git submodule add -b &lt;branch&gt; &lt;url&gt; &lt;path&gt;</code></td><td>添加子模块</td><td><code>-b</code> 跟踪分支</td></tr><tr><td><code>git submodule status --recursive</code></td><td>查看子模块状态</td><td><code>-</code> 未初始化 / <code>+</code> 指针不一致</td></tr><tr><td><code>git submodule update --init --recursive</code></td><td>初始化并检出记录版本</td><td><code>--remote</code> 取远端最新</td></tr><tr><td><code>git submodule update --remote --merge</code></td><td>更新到远端分支并合并</td><td><code>--rebase</code> 改用变基</td></tr><tr><td><code>git submodule sync --recursive</code></td><td>同步 <code>.gitmodules</code> 中的 URL</td><td>URL 迁移后必做</td></tr><tr><td><code>git submodule foreach --recursive &#39;&lt;cmd&gt;&#39;</code></td><td>对每个子模块执行命令</td><td><code>$name</code>、<code>$path</code> 变量可用</td></tr><tr><td><code>git submodule deinit -f &lt;path&gt;</code></td><td>移除子模块工作区</td><td>保留 <code>.gitmodules</code> 配置</td></tr><tr><td><code>git diff --submodule=log</code></td><td>查看子模块指针变化详情</td><td><code>--submodule=short</code></td></tr><tr><td><code>git subtree add --prefix=&lt;dir&gt; &lt;repo&gt; &lt;branch&gt; --squash</code></td><td>引入子树</td><td><code>--squash</code> 压缩历史</td></tr><tr><td><code>git subtree pull --prefix=&lt;dir&gt; &lt;repo&gt; &lt;branch&gt; --squash</code></td><td>拉取子树更新</td><td>需与 add 时策略一致</td></tr><tr><td><code>git subtree push --prefix=&lt;dir&gt; &lt;repo&gt; &lt;branch&gt;</code></td><td>把子树目录推回上游</td><td>冲突时先 pull</td></tr></tbody></table><h2 id="危险命令清单" tabindex="-1">危险命令清单 <a class="header-anchor" href="#危险命令清单" aria-label="Permalink to &quot;危险命令清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>风险</th><th>替代 / 前置动作</th></tr></thead><tbody><tr><td><code>git reset --hard</code></td><td>丢弃工作区与暂存区改动</td><td>先 <code>stash</code>；误操作后查 <a href="/git-tutorial-site/guide/mastery/01-reflog">reflog</a></td></tr><tr><td><code>git clean -fdx</code></td><td>删除所有未跟踪文件，包括 <code>.env</code></td><td>先 <code>git clean -n</code> 预览</td></tr><tr><td><code>git branch -D</code></td><td>强删未合并分支</td><td>先 <code>git branch --merged</code> 检查</td></tr><tr><td><code>git push --force</code></td><td>覆盖远端历史，可能丢失同事提交</td><td>改用 <code>--force-with-lease</code></td></tr><tr><td><code>git rebase</code> 已推送分支</td><td>他人拉取后历史分叉</td><td>只 rebase 自己未共享的分支</td></tr><tr><td><code>git commit --amend</code> 已推送提交</td><td>需要强推才能同步</td><td>已推送用新提交修正</td></tr><tr><td><code>git filter-repo</code> / <code>filter-branch</code></td><td>重写全仓库历史</td><td>先镜像备份，通知所有协作者</td></tr><tr><td><code>git reflog expire --expire=now --all</code></td><td>清空救援记录</td><td>确认无需恢复再执行</td></tr><tr><td><code>git gc --prune=now</code></td><td>立即删除不可达对象</td><td>救援期间禁用</td></tr><tr><td><code>git update-ref -d &lt;ref&gt;</code></td><td>直接删除引用，绕过检查</td><td>优先用 <code>branch -d</code></td></tr><tr><td><code>git stash drop</code> / <code>clear</code></td><td>删除 stash 记录</td><td>先 <code>git stash list</code> 确认</td></tr><tr><td><code>git checkout -- &lt;file&gt;</code></td><td>丢弃工作区改动且无提示</td><td>用 <code>git restore</code> 更明确</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">强推的唯一安全写法</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-with-lease</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>--force-with-lease</code> 会在远端分支比你上次 fetch 时更新过的情况下拒绝推送。不要使用 <code>--force</code>，也不要先 <code>fetch</code> 后仍用 <code>--force</code> 掩盖差异。</p></div><p>更多报错处理见 <a href="/git-tutorial-site/guide/appendix/02-faq">报错 FAQ</a>，常用缩写配置见 <a href="/git-tutorial-site/guide/appendix/03-alias">推荐 alias 配置</a>。</p>`,28)])])}const b=d(r,[["render",a]]);export{u as __pageData,b as default};
